 "content": "def transform(grid):
    """Return one cell per 3x3 block, preserving its non-background color."""
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            symbols = [
                grid[i][j]
                for i in range(r, min(r + 3, h))
                for j in range(c, min(c + 3, w))
                if grid[i][j] not in (0, 5)
            ]
            row.append(symbols[0] if symbols else 0)
        out.append(row)
    return out
